using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalCitySignsMeshCheck{
static BindingFlags F=BindingFlags.NonPublic|BindingFlags.Static;static Type T=typeof(FinalCitySigns);static object C(string n,params object[] a)=>T.GetMethod(n,F).Invoke(null,a);
static FinalCitySignsMeshCheck(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalCitySignsMeshCheck.request")||EditorApplication.isCompiling)return;File.Delete("FinalCitySignsMeshCheck.request");try{if(File.Exists("FinalEnvironmentRoadReview/CitySignsMeshCorrection.txt"))throw new Exception("Correction already applied");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var group=scene.GetRootGameObjects().Single(g=>g.name=="City Building Signs - Shared Atlas");var native=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.sharedMaterials.Any(m=>m&&m.name.StartsWith("Building"))&&r.GetComponent<MeshFilter>()).ToArray();string backup="FinalEnvironmentRoadBackup/CitySignsMeshCorrection-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);int moved=0,flipped=0;
foreach(var f in group.GetComponentsInChildren<MeshFilter>()){var m=f.sharedMesh;File.Copy(AssetDatabase.GetAssetPath(m),backup+"/"+Path.GetFileName(AssetDatabase.GetAssetPath(m)));var p=m.vertices;var uv=m.uv;var colors=m.colors;var r=native.OrderBy(v=>Vector3.Distance(v.bounds.center,f.transform.position)).First();var g=C("Read",r);for(int i=0;i<p.Length;i+=4){if(colors[i].a<.4f||colors[i].a>.6f)continue;float sum=uv[i].x+uv[i+2].x;for(int j=i;j<i+4;j++)uv[j].x=sum-uv[j].x;flipped++;float v=(uv[i].y+uv[i+2].y)*.5f;if(v<.5f)continue;var right=(p[i+1]-p[i]).normalized;var up=(p[i+3]-p[i]).normalized;var normal=Vector3.Cross(right,up).normalized;var center=(p[i]+p[i+1]+p[i+2]+p[i+3])*.25f;float w=Vector3.Distance(p[i],p[i+1]),h=Vector3.Distance(p[i],p[i+3]);float advance=0;
for(int x=0;x<=36;x++)for(int y=0;y<=10;y++){var q=f.transform.TransformPoint(center+right*((x/36f-.5f)*w)+up*((y/10f-.5f)*h));object[] a={g,q+normal*3,-normal,Vector3.zero,Vector3.zero};if(!(bool)C("Hit",a))continue;float depth=Vector3.Dot((Vector3)a[3]-q,normal);if(depth<1.35f)advance=Mathf.Max(advance,depth+.085f);}
if(advance>.02f){int start=Mathf.Max(0,i-24),end=i+4;for(int j=start;j<end;j++)p[j]+=normal*advance;moved++;}}
m.vertices=p;m.uv=uv;m.RecalculateBounds();EditorUtility.SetDirty(m);var lod=f.GetComponent<LODGroup>();lod.RecalculateBounds();lod.size=Mathf.Clamp(lod.size,8,24);PrefabUtility.RecordPrefabInstancePropertyModifications(lod);}
AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("FinalEnvironmentRoadReview/CitySignsMeshCorrection.txt","SUCCESS readable front UVs corrected="+flipped+"; facade panels moved beyond sampled pilasters/mullions="+moved+"; backup="+backup);File.WriteAllText("FinalCitySignsFinish.request","verify");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CitySignsMeshCheckFailure.txt",e.ToString());Debug.LogException(e);}}}
